-- Tags (hashtags) on stories: people, teams, events, products a story is
-- about. Generated by AI on save when a story has none; editable in the
-- editor; shown as #hashtags at the end of the story; used by search and by
-- /news?tag=...
ALTER TABLE articles
  ADD COLUMN IF NOT EXISTS tags TEXT[] NOT NULL DEFAULT '{}';

CREATE INDEX IF NOT EXISTS articles_tags_idx ON articles USING GIN (tags);

COMMENT ON COLUMN articles.tags IS 'Story tags, e.g. {Lakers,"LeBron James"}. Shown as hashtags.';
